alter type public.inventory_movement_type add value if not exists 'authorized_exit';
alter type public.inventory_movement_type add value if not exists 'defective';
create type public.defective_product_status as enum ('pending_supplier','delivered','replaced','resolved');
create table public.inventory_authorized_exits(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),variant_id uuid not null,quantity integer not null check(quantity>0),reason text not null check(char_length(btrim(reason)) between 3 and 300),request_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),constraint exits_variant_business foreign key(variant_id,business_id) references public.product_variants(id,business_id),constraint exits_request_unique unique(business_id,request_id));
create table public.defective_products(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),variant_id uuid not null,supplier_id uuid,quantity integer not null check(quantity>0),description text not null check(char_length(btrim(description)) between 3 and 500),status public.defective_product_status not null default 'pending_supplier',request_id uuid not null,reported_by uuid not null references auth.users(id),reported_at timestamptz not null default now(),constraint defective_variant_business foreign key(variant_id,business_id) references public.product_variants(id,business_id),constraint defective_supplier_business foreign key(supplier_id,business_id) references public.suppliers(id,business_id),constraint defective_request_unique unique(business_id,request_id));
alter table public.inventory_authorized_exits enable row level security; alter table public.defective_products enable row level security;
create policy "owners read exits" on public.inventory_authorized_exits for select to authenticated using(public.is_business_owner(business_id)); create policy "members read defectives" on public.defective_products for select to authenticated using(public.has_business_permission(business_id,'inventory.read'));
create function public.record_authorized_exit(p_business_id uuid,p_variant_id uuid,p_quantity integer,p_reason text,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare id uuid; available integer; begin if auth.uid() is null or not public.has_business_permission(p_business_id,'inventory.adjust') then raise exception 'No tienes permiso para registrar salidas.'; end if; select id into id from public.inventory_authorized_exits where business_id=p_business_id and request_id=p_request_id; if id is not null then return id; end if; select coalesce(sum(quantity_delta),0)::integer into available from public.inventory_movements where business_id=p_business_id and variant_id=p_variant_id and inventory_state='available'; if p_quantity is null or p_quantity<=0 or available<p_quantity then raise exception 'No hay existencias disponibles suficientes.'; end if; insert into public.inventory_authorized_exits(business_id,variant_id,quantity,reason,request_id,created_by) values(p_business_id,p_variant_id,p_quantity,btrim(p_reason),p_request_id,auth.uid()) returning id into id; insert into public.inventory_movements(business_id,variant_id,movement_type,inventory_state,quantity_delta,source_type,source_id,occurred_at,created_by) values(p_business_id,p_variant_id,'authorized_exit','available',-p_quantity,'authorized_exit',id,now(),auth.uid()); return id; end; $$;
create function public.report_defective_product(p_business_id uuid,p_variant_id uuid,p_supplier_id uuid,p_quantity integer,p_description text,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare id uuid; available integer; begin if auth.uid() is null or not public.has_business_permission(p_business_id,'inventory.read') then raise exception 'No tienes permiso para reportar defectuosos.'; end if; select id into id from public.defective_products where business_id=p_business_id and request_id=p_request_id; if id is not null then return id; end if; select coalesce(sum(quantity_delta),0)::integer into available from public.inventory_movements where business_id=p_business_id and variant_id=p_variant_id and inventory_state='available'; if p_quantity is null or p_quantity<=0 or available<p_quantity then raise exception 'No hay existencias disponibles suficientes.'; end if; insert into public.defective_products(business_id,variant_id,supplier_id,quantity,description,request_id,reported_by) values(p_business_id,p_variant_id,p_supplier_id,p_quantity,btrim(p_description),p_request_id,auth.uid()) returning id into id; insert into public.inventory_movements(business_id,variant_id,movement_type,inventory_state,quantity_delta,source_type,source_id,occurred_at,created_by) values(p_business_id,p_variant_id,'defective','available',-p_quantity,'defective_available',id,now(),auth.uid()),(p_business_id,p_variant_id,'defective','defective_pending',p_quantity,'defective_pending',id,now(),auth.uid()); return id; end; $$;
revoke all on function public.record_authorized_exit(uuid,uuid,integer,text,uuid) from public; grant execute on function public.record_authorized_exit(uuid,uuid,integer,text,uuid) to authenticated; revoke all on function public.report_defective_product(uuid,uuid,uuid,integer,text,uuid) from public; grant execute on function public.report_defective_product(uuid,uuid,uuid,integer,text,uuid) to authenticated;
